class ToolError(RuntimeError):
    """Expected error that is safe to return to an MCP client."""

    def __init__(self, message: str, code: str | None = None):
        super().__init__(message)
        self.code = code

import unittest
from apps.local_tools.errors import ToolError


class TestToolError(unittest.TestCase):
    def test_default_code_is_none(self):
        err = ToolError("something went wrong")
        self.assertIsNone(err.code)

    def test_custom_code_is_kept(self):
        err = ToolError("something went wrong", code="INVALID_INPUT")
        self.assertEqual(err.code, "INVALID_INPUT")

    def test_str_is_message(self):
        msg = "something went wrong"
        err = ToolError(msg)
        self.assertEqual(str(err), msg)


if __name__ == "__main__":
    unittest.main()

